    insert into public.blog_posts (status) values ('draft') returning id into pid;
  end if;
  update public.blog_posts set
    status = 'published', publish_at = coalesce(publish_at, now()),
    category_id = (select id from public.blog_categories where slug = $v$interior-design$v$),
    author_id = (select id from public.blog_authors where slug = 'vari-studio'),
    cover = $v$b80319_962a6cc04617409f94ea031705d4ee66~mv2.png$v$,
    cover_alt = $v${"en": "Vaulted timber living room with a stone fireplace in Hearthstone Haven, Telemark, Norway"}$v$::jsonb,
    faq = $v$[{"q": {"en": "Can an interior designer remove walls?"}, "a": {"en": "Not on their own if the wall is load-bearing or the change needs approval. That requires an architect or interior architect and a structural engineer, and often a permit. Non-structural partitions are a different matter, but check local rules."}}, {"q": {"en": "Is an interior architect a real architect?"}, "a": {"en": "In some countries, such as Germany, \"Innenarchitekt\" is a protected title with its own registration. Elsewhere the term is used more loosely. Check the person's registration where your project is."}}, {"q": {"en": "Who is cheaper, an architect or an interior designer?"}, "a": {"en": "It depends on scope. For a refresh, an interior designer is usually more economical. For structural work or a new building you need an architect regardless, and a good one saves money by avoiding costly mistakes."}}, {"q": {"en": "Do I need both an architect and an interior designer?"}, "a": {"en": "For new buildings and major renovations, often yes. The architect handles the building and approvals, the interior designer the spaces people live and work in. The best results come when they collaborate from the start."}}]$v$::jsonb
  where id = pid;
